import{_ as o,V as c,W as l,X as e,Z as n,a1 as s,$ as p,Y as a,F as i}from"./framework-b1bd8911.js";const u={},d=n("h1",{id:"图片风格化处理",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#图片风格化处理","aria-hidden":"true"},"#"),s(" 图片风格化处理")],-1),r=n("blockquote",null,[n("p",null,'把一张照片变成手绘素描，或者变成一张可以涂色的线稿，这类"换画风"的需求在 Java 里怎么做？本文介绍 QuickMedia 中的 photo-plugin：纯 Java 实现、不依赖任何外部环境，一行链式调用即可完成图片的风格化处理。')],-1),k=a(`<h2 id="i-问题背景" tabindex="-1"><a class="header-anchor" href="#i-问题背景" aria-hidden="true">#</a> I. 问题背景</h2><p>图片风格化，指的是不改变图片内容本身，而是改变它的&quot;画风&quot;，典型场景有：</p><ul><li>把照片转成<strong>素描画</strong>，用于生成手绘风格的头像、海报素材</li><li>把照片转成<strong>线稿（轮廓线）</strong>，用于涂色本、漫画分镜、图片轮廓提取</li></ul><p>这些效果的底层都是一些经典的图像处理算法：灰度化、卷积、高斯模糊、颜色混合。原生 JDK 的 <code>BufferedImage</code> 逐像素操作完全能实现，但每次都手写一遍太痛苦了；而像 ImageMagick 这种外部工具虽然功能强大，却需要在服务器上装环境，对于只是想&quot;加个滤镜&quot;的场景来说太重了。</p><p>photo-plugin 选择了中间路线：<strong>纯 Java 实现</strong>（基于 BufferedImage 逐像素运算，辅以 jhlabs 图像处理库），零环境依赖，引入 jar 即可使用。它把每种风格封装成一个&quot;算子&quot;（Operator），对外暴露统一的链式 API，用起来和 QuickMedia 其他插件保持了同一套手感。</p><h2 id="ii-依赖引入" tabindex="-1"><a class="header-anchor" href="#ii-依赖引入" aria-hidden="true">#</a> II. 依赖引入</h2><p>在 pom.xml 中添加依赖，请注意使用最新的版本：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.github.liuyueyi.media<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>photo-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.1.0<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>photo-plugin 内部依赖了 base-plugin 和 <code>com.github.liuyueyi:java-jhlabs</code>（灰度、反色、高斯模糊、混合模式这些基础滤镜的来源），这些会作为传递依赖自动引入，不需要手动添加。</p>`,9),g=a(`<h2 id="iii-使用姿势总览" tabindex="-1"><a class="header-anchor" href="#iii-使用姿势总览" aria-hidden="true">#</a> III. 使用姿势总览</h2><p>photo-plugin 的入口是 <code>PhotoOperateWrapper</code>，所有算子共用同一套使用姿势：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">BufferedImage</span> out <span class="token operator">=</span> <span class="token class-name">PhotoOperateWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token class-name">OperatorEnum</span><span class="token punctuation">.</span><span class="token constant">SKETCH</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setImg</span><span class="token punctuation">(</span><span class="token string">&quot;https://t7.baidu.com/it/u=4162611394,4275913936&amp;fm=193&amp;f=GIF&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">asImg</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>拆解一下这个链式调用：</p><ul><li><code>PhotoOperateWrapper.of(OperatorEnum)</code>：指定算子，当前支持 <code>SKETCH</code>（素描）和 <code>EDGE</code>（边缘检测）两种，返回对应的配置对象</li><li><code>setImg(...)</code>：指定输入图片，支持 <code>String</code> 路径（网络地址 / 本地绝对路径 / <code>~/</code> 用户目录 / classpath 相对路径）和 <code>BufferedImage</code> 对象</li><li>中间的 <code>setXxx(...)</code>：算子各自的参数配置，链式叠加</li><li><code>build()</code>：配置完成，返回 <code>PhotoOperateWrapper</code> 对象（这一步可以省略，直接接输出方法）</li><li><code>asImg()</code> / <code>asFile(fileName)</code>：输出结果，前者返回 <code>BufferedImage</code>，后者直接保存文件</li></ul><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 保存到文件</span>
<span class="token class-name">PhotoOperateWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token class-name">OperatorEnum</span><span class="token punctuation">.</span><span class="token constant">SKETCH</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setImg</span><span class="token punctuation">(</span><span class="token string">&quot;sketch_in.jpg&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">asFile</span><span class="token punctuation">(</span><span class="token string">&quot;d://quickmedia/sketch_out.png&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>asFile</code> 内部会自动创建父目录，保存的图片格式由 <code>setImgType</code> 决定（默认 <code>png</code>）。</p><h2 id="iv-素描算子-sketch" tabindex="-1"><a class="header-anchor" href="#iv-素描算子-sketch" aria-hidden="true">#</a> IV. 素描算子：SKETCH</h2><h3 id="_1-基本使用" tabindex="-1"><a class="header-anchor" href="#_1-基本使用" aria-hidden="true">#</a> 1. 基本使用</h3><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testSketch</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">BufferedImage</span> out <span class="token operator">=</span> <span class="token class-name">PhotoOperateWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token class-name">OperatorEnum</span><span class="token punctuation">.</span><span class="token constant">SKETCH</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">setImg</span><span class="token punctuation">(</span><span class="token string">&quot;https://t7.baidu.com/it/u=4162611394,4275913936&amp;fm=193&amp;f=GIF&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">asImg</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;----&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,10),m=a(`<h3 id="_2-效果说明" tabindex="-1"><a class="header-anchor" href="#_2-效果说明" aria-hidden="true">#</a> 2. 效果说明</h3><p>不设置任何参数，得到的就是一张标准的手绘素描效果：主体轮廓以深色铅笔线条呈现，原图中的大块色彩被&quot;抹掉&quot;，只留下明暗和纹理。</p><h3 id="_3-参数调节" tabindex="-1"><a class="header-anchor" href="#_3-参数调节" aria-hidden="true">#</a> 3. 参数调节</h3><p>素描算子提供了两个可调参数：</p><table><thead><tr><th style="text-align:center;">参数</th><th style="text-align:center;">类型</th><th style="text-align:center;">默认值</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;"><code>radius</code></td><td style="text-align:center;">float</td><td style="text-align:center;">20f</td><td>高斯模糊半径，控制笔触的柔和程度。值越大，模糊越厉害，素描线条越柔和；值越小，保留的原图细节越多，线条越&quot;锐利&quot;</td></tr><tr><td style="text-align:center;"><code>alpha</code></td><td style="text-align:center;">float</td><td style="text-align:center;">1.0f</td><td>颜色减淡混合的强度，影响画面的明暗对比</td></tr></tbody></table><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 笔触更柔和的素描</span>
<span class="token class-name">BufferedImage</span> out <span class="token operator">=</span> <span class="token class-name">PhotoOperateWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token class-name">OperatorEnum</span><span class="token punctuation">.</span><span class="token constant">SKETCH</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setImg</span><span class="token punctuation">(</span><span class="token string">&quot;in.jpg&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setRadius</span><span class="token punctuation">(</span><span class="token number">40f</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setAlpha</span><span class="token punctuation">(</span><span class="token number">1.0f</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">asImg</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-实现原理" tabindex="-1"><a class="header-anchor" href="#_4-实现原理" aria-hidden="true">#</a> 4. 实现原理</h3><p>素描的算法流程是经典的&quot;颜色减淡&quot;（Color Dodge）玩法，一共四步：</p><ol><li><strong>灰度化</strong>：用 <code>GrayscaleFilter</code> 把彩色图变成灰度图，这一步去掉了所有颜色信息，只保留明暗</li><li><strong>反色</strong>：用 <code>InvertFilter</code> 对灰度图做反色（黑变白、白变黑）</li><li><strong>高斯模糊</strong>：对反色后的图做高斯模糊（半径即 <code>radius</code> 参数），让边缘发散</li><li><strong>颜色减淡混合</strong>：将模糊后的反色图与原始灰度图做 ColorDodge 混合（混合强度即 <code>alpha</code> 参数）</li></ol><p>ColorDodge 混合的直观理解是：结果 = 底图 / (1 - 顶图)。反色图模糊之后，原图的轮廓处颜色深、平坦区颜色浅，两者相除之后，平坦区域会被&quot;提亮&quot;到接近白色，而轮廓区域保持深色——于是画面上就只剩下了深色的轮廓线条，这正是素描的视觉效果。这套流程在网上被称为&quot;PS 素描滤镜&quot;的算法版，很多语言都有等价实现。</p><h2 id="v-边缘检测算子-edge" tabindex="-1"><a class="header-anchor" href="#v-边缘检测算子-edge" aria-hidden="true">#</a> V. 边缘检测算子：EDGE</h2><h3 id="_1-基本使用-1" tabindex="-1"><a class="header-anchor" href="#_1-基本使用-1" aria-hidden="true">#</a> 1. 基本使用</h3><p>边缘检测算子的配置项比素描多，先看一个使用 <code>parse</code> 方式的完整示例（官方测试 case）：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testSobel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">BufferedImage</span> out <span class="token operator">=</span> <span class="token class-name">PhotoOperateWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token class-name">OperatorEnum</span><span class="token punctuation">.</span><span class="token constant">EDGE</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">parse</span><span class="token punctuation">(</span><span class="token class-name">EdgeOperator<span class="token punctuation">.</span>EdgeOperateOptions</span><span class="token punctuation">.</span><span class="token function">type</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>  <span class="token comment">// 拿到 EDGE 算子的专属配置</span>
            <span class="token punctuation">.</span><span class="token function">setType</span><span class="token punctuation">(</span><span class="token class-name">EdgeOperator<span class="token punctuation">.</span>EdgeType</span><span class="token punctuation">.</span><span class="token constant">SOBEL</span><span class="token punctuation">)</span>           <span class="token comment">// 指定边缘检测算法</span>
            <span class="token punctuation">.</span><span class="token function">setBgColor</span><span class="token punctuation">(</span><span class="token class-name">Color</span><span class="token punctuation">.</span><span class="token constant">WHITE</span><span class="token punctuation">)</span>                        <span class="token comment">// 背景色：白</span>
            <span class="token punctuation">.</span><span class="token function">setLineColor</span><span class="token punctuation">(</span><span class="token class-name">Color</span><span class="token punctuation">.</span><span class="token constant">BLACK</span><span class="token punctuation">)</span>                      <span class="token comment">// 线条色：黑</span>
            <span class="token punctuation">.</span><span class="token function">setImg</span><span class="token punctuation">(</span><span class="token string">&quot;https://img2.woyaogexing.com/2017/05/24/432c24863a7ab65a!600x600.jpg&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">asImg</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;----&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里有个使用上的小细节值得说明：<code>PhotoOperateWrapper.of(OperatorEnum.EDGE)</code> 返回的声明类型是通用的 <code>OperateOptions</code>，而 <code>setType</code>、<code>setThreshold</code> 这些是 EDGE 算子专属的配置方法。要调用它们，有两种姿势：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 姿势一：parse 方式，通过 EdgeOperateOptions.type() 把配置对象&quot;还原&quot;为专属类型</span>
<span class="token class-name">PhotoOperateWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token class-name">OperatorEnum</span><span class="token punctuation">.</span><span class="token constant">EDGE</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">parse</span><span class="token punctuation">(</span><span class="token class-name">EdgeOperator<span class="token punctuation">.</span>EdgeOperateOptions</span><span class="token punctuation">.</span><span class="token function">type</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setType</span><span class="token punctuation">(</span><span class="token class-name">EdgeOperator<span class="token punctuation">.</span>EdgeType</span><span class="token punctuation">.</span><span class="token constant">SOBEL</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span>

<span class="token comment">// 姿势二：强转</span>
<span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">EdgeOperator<span class="token punctuation">.</span>EdgeOperateOptions</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">PhotoOperateWrapper</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">)</span> <span class="token class-name">PhotoOperateWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token class-name">OperatorEnum</span><span class="token punctuation">.</span><span class="token constant">EDGE</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setType</span><span class="token punctuation">(</span><span class="token class-name">EdgeOperator<span class="token punctuation">.</span>EdgeType</span><span class="token punctuation">.</span><span class="token constant">CANNY</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>两种写法效果等价，<code>parse</code> 的写法链式调用更顺滑一些。</p><h3 id="_2-内置的六种算法" tabindex="-1"><a class="header-anchor" href="#_2-内置的六种算法" aria-hidden="true">#</a> 2. 内置的六种算法</h3><p>边缘检测通过 <code>EdgeType</code> 枚举切换，一共内置六种算法：</p><table><thead><tr><th style="text-align:center;">EdgeType</th><th style="text-align:center;">卷积核尺寸</th><th style="text-align:center;">默认阈值</th><th>特点</th></tr></thead><tbody><tr><td style="text-align:center;"><code>SOBEL</code>（默认）</td><td style="text-align:center;">3x3</td><td style="text-align:center;">200</td><td>最常用的梯度算子，对水平/垂直边缘响应好，抗噪能力中等</td></tr><tr><td style="text-align:center;"><code>PREWITT</code></td><td style="text-align:center;">3x3</td><td style="text-align:center;">200</td><td>与 Sobel 类似的简化版，权重均匀，效果略平一些</td></tr><tr><td style="text-align:center;"><code>KIRSCH</code></td><td style="text-align:center;">3x3</td><td style="text-align:center;">200</td><td>八方向卷积取最大值，对斜向边缘更敏感</td></tr><tr><td style="text-align:center;"><code>LAPLACIAN</code></td><td style="text-align:center;">3x3</td><td style="text-align:center;">50</td><td>二阶导数算子，对细节和噪声都很敏感，线条更碎</td></tr><tr><td style="text-align:center;"><code>ROBERTS</code></td><td style="text-align:center;">2x2</td><td style="text-align:center;">50</td><td>最小的 2x2 算子，计算快，但抗噪能力弱</td></tr><tr><td style="text-align:center;"><code>CANNY</code></td><td style="text-align:center;">-</td><td style="text-align:center;">-</td><td>完整的多阶段边缘检测算法，线条连续性最好，推荐</td></tr></tbody></table><p>默认阈值因算法而异（梯度量级不同），实际使用时按图片效果微调即可。</p><h3 id="_3-参数说明" tabindex="-1"><a class="header-anchor" href="#_3-参数说明" aria-hidden="true">#</a> 3. 参数说明</h3><p><code>EdgeOperateOptions</code> 提供四个配置项：</p><table><thead><tr><th style="text-align:center;">参数</th><th style="text-align:center;">默认值</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;"><code>type</code></td><td style="text-align:center;"><code>SOBEL</code></td><td>边缘检测算法</td></tr><tr><td style="text-align:center;"><code>threshold</code></td><td style="text-align:center;">各算法自带默认值</td><td>边缘判定阈值：梯度值大于阈值的像素判为边缘（画线条色），否则判为背景（画背景色）。<strong>阈值越小，保留的边缘越多，画面越&quot;密&quot;；越大则只剩最显著的轮廓</strong></td></tr><tr><td style="text-align:center;"><code>bgColor</code></td><td style="text-align:center;">黑</td><td>背景色，支持 <code>Color</code> 对象或 int 色值</td></tr><tr><td style="text-align:center;"><code>lineColor</code></td><td style="text-align:center;">白</td><td>线条颜色</td></tr></tbody></table><p>也就是说，默认输出是&quot;黑底白线&quot;，想得到常见的&quot;白底黑线&quot;涂色本线稿，把两个颜色对调即可。</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 白底黑线的 Canny 线稿（官方测试 case）</span>
<span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testCanny</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">BufferedImage</span> out <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token class-name">EdgeOperator<span class="token punctuation">.</span>EdgeOperateOptions</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">PhotoOperateWrapper</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">)</span> <span class="token class-name">PhotoOperateWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token class-name">OperatorEnum</span><span class="token punctuation">.</span><span class="token constant">EDGE</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">setType</span><span class="token punctuation">(</span><span class="token class-name">EdgeOperator<span class="token punctuation">.</span>EdgeType</span><span class="token punctuation">.</span><span class="token constant">CANNY</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">setBgColor</span><span class="token punctuation">(</span><span class="token class-name">Color</span><span class="token punctuation">.</span><span class="token constant">WHITE</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">setLineColor</span><span class="token punctuation">(</span><span class="token class-name">Color</span><span class="token punctuation">.</span><span class="token constant">BLACK</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">setImg</span><span class="token punctuation">(</span><span class="token string">&quot;https://img0.baidu.com/it/u=591720380,976271434&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=500&amp;h=1111&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">build</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">asImg</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;----&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,26),h=a('<h3 id="_4-各算法的效果差异与选择建议" tabindex="-1"><a class="header-anchor" href="#_4-各算法的效果差异与选择建议" aria-hidden="true">#</a> 4. 各算法的效果差异与选择建议</h3><p>同样是白底黑线的配置，不同算法输出的线稿风格差异挺明显：</p><ul><li><strong>SOBEL / PREWITT</strong>：线条粗细均匀，主要是横竖两个方向的轮廓，适合快速出&quot;简笔画&quot;风格的线稿</li><li><strong>KIRSCH</strong>：八方向扫描，斜向线条（如头发丝、树叶边缘）保留得更全，但画面也会显得更密</li><li><strong>LAPLACIAN</strong>：二阶导数，对细微纹理敏感，出来的线条比较碎，适合纹理提取而不是整图线稿</li><li><strong>ROBERTS</strong>：计算量最小，效果也最&quot;糙&quot;，适合对性能敏感、对效果要求不高的场景</li><li><strong>CANNY</strong>：线条最连续、最干净，几乎只有真正的物体轮廓，做涂色线稿首选</li></ul><p>一个实用提示：除 CANNY 外的几种算法在实现上是逐像素 <code>getRGB</code>/<code>setRGB</code> 的方式做卷积，<strong>大图处理会比较慢</strong>，使用前建议先把图片压缩到合适的尺寸（可以配合 imagic-plugin 的 <code>scale</code> 先做一步缩放）；Canny 内部使用整型数组一次性处理，相对高效一些。</p><h2 id="vi-canny-边缘检测原理简述" tabindex="-1"><a class="header-anchor" href="#vi-canny-边缘检测原理简述" aria-hidden="true">#</a> VI. Canny 边缘检测原理简述</h2>',5),v=n("code",null,"com.github.hui.quick.plugin.photo.util.CannyFilter",-1),b={href:"https://blog.csdn.net/yeweij226/article/details/99747631",target:"_blank",rel:"noopener noreferrer"},f=a(`<ol><li><strong>灰度化</strong>：把彩色图按 <code>0.299R + 0.587G + 0.114B</code> 的亮度公式转成灰度图，边缘检测只关心亮度突变，不关心颜色</li><li><strong>高斯平滑</strong>：用高斯核对图片做平滑滤波，抹掉细小的噪声点。这一步很关键——不做平滑的话，噪声会被当成&quot;边缘&quot;检测出来。平滑力度由 <code>gaussianKernelRadius</code> 控制</li><li><strong>计算梯度</strong>：对平滑后的图计算每个像素的梯度幅值和方向（亮度变化最剧烈的地方就是边缘的候选位置）</li><li><strong>非极大值抑制</strong>（Non-Maximum Suppression）：边缘候选点沿梯度方向只保留幅值最大的那个点，把&quot;粗边&quot;细化成一条像素宽的细线，同时排除不是局部最大的伪边缘</li><li><strong>双阈值 + 滞后连接</strong>（Hysteresis）：设定高、低两个阈值（即 <code>highThreshold</code> 和 <code>lowThreshold</code>）。梯度高于高阈值的一定为边缘；低于低阈值的一定不是；介于两者之间的像素，只有当它与已确定的边缘连通时才算边缘。这一步把断裂的弱边缘&quot;接&quot;回强边缘，让线条保持连续</li></ol><p>CannyFilter 对外暴露了几个可调参数（低阈值、高阈值、高斯核半径等），不过在 EDGE 算子中调用时，内部固定使用了 <code>lowThreshold = 0.5f</code>、<code>highThreshold = 1.5f</code> 的经验值，通常不需要干预。如果想体验参数调节，也可以直接拿 <code>CannyFilter</code> 来用：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">CannyFilter</span> detector <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">CannyFilter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
detector<span class="token punctuation">.</span><span class="token function">setLowThreshold</span><span class="token punctuation">(</span><span class="token number">0.5f</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
detector<span class="token punctuation">.</span><span class="token function">setHighThreshold</span><span class="token punctuation">(</span><span class="token number">1.5f</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
detector<span class="token punctuation">.</span><span class="token function">setSourceImage</span><span class="token punctuation">(</span>img<span class="token punctuation">)</span><span class="token punctuation">;</span>
detector<span class="token punctuation">.</span><span class="token function">process</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">BufferedImage</span> edges <span class="token operator">=</span> detector<span class="token punctuation">.</span><span class="token function">getEdgesImage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="vii-小结" tabindex="-1"><a class="header-anchor" href="#vii-小结" aria-hidden="true">#</a> VII. 小结</h2><p>本文介绍了 photo-plugin 的完整用法：</p><ul><li><strong>SKETCH 素描</strong>：灰度 → 反色 → 高斯模糊 → ColorDodge 混合，<code>radius</code> 控制笔触柔度，<code>alpha</code> 控制对比强度</li><li><strong>EDGE 边缘检测</strong>：六种算法（SOBEL / PREWITT / KIRSCH / LAPLACIAN / ROBERTS / CANNY）可切换，线条色、背景色、阈值均可定制，CANNY 效果最好，是线稿场景的首选</li></ul><p>整个插件纯 Java 实现，零外部环境依赖，配合 QuickMedia 的 image-plugin（图片合成）和 imagic-plugin（基于 ImageMagick 的图片编辑），基本可以覆盖&quot;图片加工&quot;的大部分场景。</p><p><strong>项目地址：</strong></p>`,8),y={href:"https://github.com/liuyueyi/quick-media",target:"_blank",rel:"noopener noreferrer"},x=n("li",null,[n("code",null,"QuickMedia"),s(" 目标是创建一个专注图文，音视频，二维码处理的开源项目")],-1),E=n("p",null,[n("strong",null,"相关参考：")],-1),_={href:"https://github.com/liuyueyi/quick-media/blob/master/plugins/photo-plugin/src/test/java/com/github/hui/quick/plugin/photo/test/PhotoTest.java",target:"_blank",rel:"noopener noreferrer"},q={href:"https://github.com/liuyueyi/quick-media/blob/master/plugins/photo-plugin/src/test/java/com/github/hui/quick/plugin/photo/test/EdgeTest.java",target:"_blank",rel:"noopener noreferrer"};function I(O,C){const t=i("ExternalLinkIcon");return c(),l("div",null,[d,r,e(" more "),k,e(` 说明：若 maven 中央仓库暂未同步最新版本，可使用源码仓库自行安装：
https://github.com/liuyueyi/quick-media `),g,e(" 效果图待补充：testSketch 输出的素描效果图（原图与素描效果对比） "),m,e(" 效果图待补充：testCanny / testSobel 输出的线稿效果图对比（CANNY vs SOBEL，同为白底黑线） "),h,n("p",null,[s("Canny 是边缘检测领域的经典算法（1986 年由 John Canny 提出），photo-plugin 在 "),v,s(" 中做了完整的纯 Java 移植（实现思路参考："),n("a",b,[s("Canny 边缘检测的 Java 实现"),p(t)]),s("）。整个流程分五步：")]),f,n("ul",null,[n("li",null,[n("a",y,[s("https://github.com/liuyueyi/quick-media"),p(t)])]),x]),E,n("ul",null,[n("li",null,[s("官方使用 case："),n("a",_,[s("PhotoTest"),p(t)]),s(" / "),n("a",q,[s("EdgeTest"),p(t)])])])])}const j=o(u,[["render",I],["__file","01.图片风格化处理.html.vue"]]);export{j as default};
